function ogCoOut(d){var c=coCur(),l=(A.d.deptCos||{})[d.id]||[];return !!c&&l.length>0&&l.indexOf(c)<0}
function ogDepts(){return ogAct('departments').filter(function(d){return !ogCoOut(d)})}
