function ogFlow(d){return (A.d.flowDept||{})[d]||A.d.flowDefault||'lead'}
function ogPersonFlow(e){if(e.approver2_id==='none')return 'ขั้นเดียว (ไม่มีขั้นที่ 2)';if(e.approver2_id&&e.approver2_id!=='dept'){var a=ogEmp(e.approver2_id);return 'ขั้นที่ 2: '+(a?esc(a.first_name+' '+(a.last_name||'')):'(ผู้อนุมัติลาออกแล้ว)')}return e.approval_flow?OGF[e.approval_flow]||e.approval_flow:''}
