  T.forEach(function(t){var l=ogLead(t);if(l&&l.department_id!==t.department_id)I.push({k:'t',id:t.id,t:'หัวหน้าทีมอยู่คนละแผนกกับทีม',s:t.name+' · '+(l.nickname||l.first_name),why:'ตรวจว่าตั้งใจหรือไม่',act:'ตรวจ'})});
