function ogMiss(d){var T=ogAct('teams').filter(function(t){return t.department_id===d.id}),n=0;if(ogDeptEmps(d.id).length&&!ogHeads(d.id).length)n++;T.forEach(function(t){if(ogMembers(t.id).length&&!ogLead(t))n++});return n}
function ogWho(e,role,act){return '<span class="og3-who">'+av(e,30)+'<span><b>'+esc(e.first_name+' '+(e.last_name||''))+'</b>'+(e.nickname?'<small>'+esc(e.nickname)+(role?' · '+role:'')+'</small>':role?'<small>'+role+'</small>':'')+'</span></span>'+(act||'')}
function ogNone(t,act){return '<span class="og3-none"><i></i>'+t+'</span>'+(act||'')}
function ogMenu(btn,items){var old=document.querySelector('.og3-menu');if(old){var same=old._b===btn;old.remove();if(same)return}var m=document.createElement('div');m.className='og3-menu';m._b=btn;
  m.innerHTML=items.map(function(x,i){return '<button type="button" data-i="'+i+'"'+(x[2]?' class="bad"':'')+'>'+x[0]+'</button>'}).join('');document.body.appendChild(m);var r=btn.getBoundingClientRect();m.style.top=(r.bottom+window.scrollY+4)+'px';m.style.left=Math.max(8,r.right+window.scrollX-m.offsetWidth)+'px';
  m.onclick=function(e){var b=e.target.closest('[data-i]');if(!b)return;m.remove();items[+b.dataset.i][1]()};setTimeout(function(){document.addEventListener('click',function f(e){if(!m.contains(e.target)&&e.target!==btn){m.remove();document.removeEventListener('click',f)}})},0)}
function ogPosOf(d){var E=ogDeptEmps(d.id);return ogAct('positions').map(function(p){var pl=posPl(p),mine=pl.some(function(x){return x.d===d.id});return {p:p,mine:mine,n:E.filter(function(e){return e.position_id===p.id}).length,all:!pl.length&&!p.department_id}}).filter(function(x){return x.mine||x.n})}
/* รอบ 4 (13 พ.ย. 2569 ผู้ใช้: "ไม่สวย เรียงไม่ตรง กระจัดกระจาย dropdown ไม่สวย") · ทีมเป็นตารางคอลัมน์คงที่ · กว้างสุด 1180px · ผู้อนุมัติเป็นปุ่มเลือก 4 แบบ + ขั้นตอนเป็นกล่องเลข */
function ogPerson(e,role,attr,empty){return '<button type="button" class="og4-pc'+(e?'':' none')+'" '+attr+'>'+(e?av(e,32):'<i class="og4-ph"></i>')+'<span class="og4-pn"><b>'+(e?esc(e.first_name+' '+(e.last_name||'')):empty)+'</b><small>'+(e?esc((e.nickname?e.nickname+' · ':'')+role):'กดเพื่อเลือกคน')+'</small></span><span class="og4-ed">'+(e?'เปลี่ยน':'ตั้ง')+'</span></button>'}
